+	spin_unlock_irqrestore(&cctx->lock, flags);
+
+	if (!rpdev)
+		return -EPIPE;
 
-	return  __fastrpc_buf_alloc(fl, rdev, size, obuf);
+	ret = __fastrpc_buf_alloc(fl, &rpdev->dev, size, obuf);
+	put_device(&rpdev->dev);
+
+	return ret;
 }
 
