--- a/drivers/rapidio/rio_cm.c
+++ b/drivers/rapidio/rio_cm.c
@@ -1602,7 +1602,7 @@ static int cm_ep_get_list(void __user *arg)
 
 	((u32 *)buf)[0] = i; /* report an updated number of entries */
