index b5f63f2f726be..10deab847ee71 100644
--- a/mm/damon/core.c
+++ b/mm/damon/core.c
@@ -1433,21 +1433,33 @@ static struct damon_target *damon_nth_target(int n, struct damon_ctx *ctx)
